    while(j<(int)R.size()) a[k++]=R[j++];

}

void ms(vector<int>&a,int l,int r){

    if(l>=r) return;

    int m=(l+r)/2; ms(a,l,m); ms(a,m+1,r); merge(a,l,m,r);

}

